style.css:
@-moz-document domain("roblox.com") {
html, body {
        background: url("https://media.giphy.com/media/v1.Y2lkPTc5MGI3NjExNThlM2w2b3BtOXFzYTN3d2k1aTczdW1xdWhqbnZyY3ZrcjkzYWExMiZlcD12MV9naWZzX3NlYXJjaCZjdD1n/VbnUQpnihPSIgIXuZv/giphy.gif") no-repeat center center fixed !important;
        background-size: cover !important;
        color: white !important;
    }

    /* Darken page content areas */
    .container, .content, .section, .game-card-container, .navbar, .footer, .header {
        background-color: rgba(0, 0, 0, 0.7) !important;
        color: white !important;
    }

    /* Style links and buttons */
    a, button {
        color: #fff !important;
        background-color: rgba(20, 20, 20, 0.7) !important;
    }

    /* Style input fields */
    input, textarea, select {
        background-color: rgba(50, 50, 50, 0.8) !important;
        color: #fff !important;
        border: 1px solid #aaa !important;
    }
}
